The simplest spiking neuron model, from the webinar for the German Neuroscience Olympiad 2020. Everything on this page runs in your browser; nothing to install. Change a slider while a simulation is running and it reacts immediately.


Code
exFont = "16px " + getComputedStyle(document.body).fontFamily
exFg = () =&gt; getComputedStyle(document.body).color
mkCanvas = (W, H) =&gt; {
  const c = DOM.context2d(W, H);
  c.canvas.style.width = "100%"; c.canvas.style.maxWidth = W + "px"; c.canvas.style.height = "auto";
  return c;
}
axisBox = (c, x, y, w, h) =&gt; { c.strokeStyle = "#999"; c.lineWidth = 1; c.strokeRect(x, y, w, h); }






























The neuron’s membrane potential \(V\) integrates its input current \(I\) and leaks back towards rest. Whenever \(V\) reaches the threshold \(V_{\text{th}}\), a spike is emitted and \(V\) is reset.
\[\tau_m \frac{dV}{dt} = (V_{\text{rest}} - V) + R\,I(t)\]

\(V\): membrane potential in mV. \(V_{\text{rest}} = -65\) mV is the resting potential it leaks back to; after a spike it is reset to \(V_{\text{reset}} = -70\) mV and held there for a refractory period of 2 ms.
\(I(t)\): input current in nA. With noise switched on, a random Gaussian fluctuation is added at every time step; the slider sets its strength.
\(\tau_m\): membrane time constant in ms, how quickly \(V\) follows a change in input.
\(R = 2\) MΩ: input resistance, fixed. \(V_{\text{th}}\): the threshold slider.



Code
viewof lifI = Inputs.range([0, 25], {value: 8, step: 0.5, label: "Input current (nA)"})
viewof lifNoise = Inputs.range([0, 10], {value: 0, step: 0.5, label: "Input noise (0 = off)"})
viewof lifTau = Inputs.range([2, 50], {value: 10, step: 1, label: "Membrane time constant τ (ms)"})
viewof lifThr = Inputs.range([-60, -35], {value: -50, step: 1, label: "Threshold (mV)"})
viewof lifPause = Inputs.toggle({label: "Pause"})
viewof lifReset = Inputs.button("Reset (also clears the f-I points)")














































Code
lifState = {
  lifReset;
  const dt = 0.1, win = 300, R = 2, Vrest = -65, Vreset = -70, refr = 2;
  const n = Math.round(win / dt);
  const V = new Float32Array(n).fill(Vrest), Iarr = new Float32Array(n);
  let v = Vrest, refrLeft = 0, t = 0;
  const fi = new Map();
  let key = null, sinceChange = 0, spikesSince = 0, lastSig = 0;
  const gauss = () =&gt; { let u = 0; while (u === 0) u = Math.random();
                        return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * Math.random()); };
  while (true) {
    const I0 = viewof lifI.value, sig = viewof lifNoise.value,
          tau = viewof lifTau.value, thr = viewof lifThr.value;
    if (!viewof lifPause.value) {
      const k = `${I0}|${sig &gt; 0}`;
      if (sig &gt; 0 && sig !== lastSig) { for (const [kk, p] of fi) if (p.noisy) fi.delete(kk); }
      if (sig &gt; 0) lastSig = sig;
      if (k !== key) { key = k; sinceChange = 0; spikesSince = 0; }
      for (let s = 0; s &lt; 20; s++) {
        const I = I0 + sig * gauss() / Math.sqrt(dt);
        if (refrLeft &gt; 0) { refrLeft -= dt; v = Vreset; }
        else {
          v += dt / tau * ((Vrest - v) + R * I);
          if (v &gt;= thr) { v = 20; spikesSince++; refrLeft = refr; }
        }
        V.copyWithin(0, 1); V[n - 1] = v;
        Iarr.copyWithin(0, 1); Iarr[n - 1] = I;
        if (v === 20) v = Vreset;
        t += dt; sinceChange += dt;
      }
      if (sinceChange &gt;= 500) fi.set(key, {I: I0, noisy: sig &gt; 0, rate: 1000 * spikesSince / sinceChange});
    }
    yield {V, Iarr, t, win, fi, thr, tau, sig, I0, R, Vrest, refr,
           rate: sinceChange &gt; 0 ? 1000 * spikesSince / sinceChange : 0};
  }
}
lifCanvas = mkCanvas(760, 360)


















Code
{
  const {V, Iarr, win, fi, thr, tau, sig, I0, R, Vrest, refr, rate} = lifState;
  const blue = "#1f77b4", orange = "#ff7f0e", c = lifCanvas, fg = exFg();
  const W = 760, H = 360, n = V.length;
  c.clearRect(0, 0, W, H); c.font = exFont;
  // traces, left
  const mL = 80, trR = 470;
  const top = {y0: 12, h: 80, lo: -10, hi: 35};
  const bot = {y0: 112, h: 200, lo: -80, hi: 30};
  const sx = i =&gt; mL + (trR - mL) * i / (n - 1);
  const sy = (p, v) =&gt; p.y0 + p.h * (1 - (v - p.lo) / (p.hi - p.lo));
  for (const p of [top, bot]) axisBox(c, mL, p.y0, trR - mL, p.h);
  c.fillStyle = fg; c.textAlign = "right";
  c.fillText("I (nA)", mL - 8, top.y0 + top.h / 2 + 5);
  c.fillText("V (mV)", mL - 8, bot.y0 + bot.h / 2 + 5);
  c.fillText(thr, mL - 8, sy(bot, thr) + 5); c.fillText("-65", mL - 8, sy(bot, -65) + 5);
  c.textAlign = "center"; c.fillText(`last ${win} ms`, (mL + trR) / 2, H - 14);
  c.textAlign = "right"; c.fillText(`${rate.toFixed(0)} spikes / s`, trR - 8, bot.y0 + 20);
  c.setLineDash([4, 4]); c.strokeStyle = "red"; c.beginPath(); c.moveTo(mL, sy(bot, thr)); c.lineTo(trR, sy(bot, thr)); c.stroke(); c.setLineDash([]);
  c.strokeStyle = "#888"; c.lineWidth = 1; c.beginPath();
  for (let i = 0; i &lt; n; i++) { const y = sy(top, Math.max(top.lo, Math.min(top.hi, Iarr[i]))); i ? c.lineTo(sx(i), y) : c.moveTo(sx(0), y); }
  c.stroke();
  c.strokeStyle = sig &gt; 0 ? orange : blue; c.lineWidth = 1.5; c.beginPath();
  for (let i = 0; i &lt; n; i++) i ? c.lineTo(sx(i), sy(bot, V[i])) : c.moveTo(sx(0), sy(bot, V[0]));
  c.stroke();
  // f-I curve, right
  const fP = {x0: 560, y0: 12, w: 180, h: 300};
  const Imax = 25, fmax = Math.max(100, ...Array.from(fi.values()).map(p =&gt; p.rate)) * 1.1;
  const fx = I =&gt; fP.x0 + fP.w * I / Imax, fy = f =&gt; fP.y0 + fP.h * (1 - f / fmax);
  axisBox(c, fP.x0, fP.y0, fP.w, fP.h);
  c.fillStyle = fg; c.textAlign = "center";
  c.fillText("input (nA)", fP.x0 + fP.w / 2, H - 14);
  c.fillText("0", fx(0), fP.y0 + fP.h + 20); c.fillText(Imax, fx(Imax), fP.y0 + fP.h + 20);
  c.save(); c.translate(fP.x0 - 44, fP.y0 + fP.h / 2); c.rotate(-Math.PI / 2); c.fillText("spikes / s", 0, 0); c.restore();
  c.textAlign = "right"; c.fillText("0", fP.x0 - 6, fy(0) + 5); c.fillText(fmax.toFixed(0), fP.x0 - 6, fy(fmax) + 5);
  c.setLineDash([3, 3]); c.strokeStyle = blue; c.lineWidth = 1; c.beginPath(); let started = false;
  for (let I = 0; I &lt;= Imax; I += 0.1) {
    const d = R * I - (thr - Vrest); if (d &lt;= 0) continue;
    const f = Math.min(fmax, 1000 / (refr + tau * Math.log(R * I / d)));
    started ? c.lineTo(fx(I), fy(f)) : c.moveTo(fx(I), fy(f)); started = true;
  }
  c.stroke(); c.setLineDash([]);
  for (const [k, p] of fi) { c.fillStyle = p.noisy ? orange : blue; c.beginPath(); c.arc(fx(p.I), fy(p.rate), 5, 0, 2 * Math.PI); c.fill(); }
  c.strokeStyle = sig &gt; 0 ? orange : blue; c.lineWidth = 2; c.beginPath(); c.arc(fx(I0), fy(Math.min(rate, fmax)), 8, 0, 2 * Math.PI); c.stroke();
  c.textAlign = "left"; c.fillStyle = blue; c.fillText("noise-free", fP.x0 + 8, fP.y0 + 22);
  c.fillStyle = orange; c.fillText(sig &gt; 0 ? `noise ${sig}` : "noise (off)", fP.x0 + 8, fP.y0 + 44);
  return c.canvas;
}







What you see. Left, top: the input current \(I\) in grey, over the last 300 ms. Left, bottom: the membrane potential \(V\), blue when the input is noise-free, orange when noise is on. The red dashed line is the threshold; the spikes are drawn as vertical strokes up to +20 mV. The number in the corner is the current firing rate.
Right: the f-I curve, firing rate against input current. Every input strength you try adds a dot once the neuron has run for half a second at that setting; blue dots are noise-free measurements, orange dots are measurements at the current noise level (changing the noise level clears them). The open ring marks the setting you are looking at now. The blue dashed line is the exact rate of the noise-free neuron, \(f = 1 / \left(t_{\text{ref}} + \tau_m \ln \frac{RI}{RI - (V_{\text{th}} - V_{\text{rest}})}\right)\), which is zero below \(I = (V_{\text{th}} - V_{\text{rest}})/R\). Noise lets the neuron fire below that point and rounds off the curve.
Try: increase the current until the neuron starts to fire, then add noise at a sub-threshold current. From the webinar for the German Neuroscience Olympiad 2020. Notebook on GitHub · Open in Google Colab

Three learning rules for a neuron with two inputs, watched in the plane of its two weights. Everything on this page runs in your browser; nothing to install. Change a slider while a simulation is running and it reacts immediately.


Code
exFont = "16px " + getComputedStyle(document.body).fontFamily
exFg = () =&gt; getComputedStyle(document.body).color
mkCanvas = (W, H) =&gt; {
  const c = DOM.context2d(W, H);
  c.canvas.style.width = "100%"; c.canvas.style.maxWidth = W + "px"; c.canvas.style.height = "auto";
  return c;
}
axisBox = (c, x, y, w, h) =&gt; { c.strokeStyle = "#999"; c.lineWidth = 1; c.strokeRect(x, y, w, h); }






























One neuron receives two inputs with activities \(u_1, u_2\) through weights \(w = (w_1, w_2)\). Averaged over many input patterns, learning is driven by the input correlation matrix \(Q = \langle u u^{\mathsf T} \rangle\), here \(Q = \begin{pmatrix} 1 & q \\ q & 1 \end{pmatrix}\), where \(q\) is the correlation between the two inputs (the slider). \(\tau\) sets the learning speed and \(\alpha\) is the strength of the normalising term in Oja’s rule. Three rules:
\[\text{Hebbian:}\quad \tau \frac{dw}{dt} = Q\,w\]
\[\text{with bounds:}\quad \tau \frac{dw}{dt} = Q\,w, \qquad 0 \le w_i \le 1\]
\[\text{Oja:}\quad \tau \frac{dw}{dt} = Q\,w - \alpha\,(w^{\mathsf T} Q\, w)\,w\]
Pick a rule, then click anywhere in the weight plane to choose an initial condition.


Code
viewof hbRule = Inputs.radio(new Map([["Hebbian", "hebb"], ["Hebbian with bounds [0, 1]", "bounded"], ["Oja's rule", "oja"]]), {value: "hebb", label: "Rule"})
viewof hbQ = Inputs.range([-1, 1], {value: -0.4, step: 0.05, label: "Input correlation q"})
viewof hbAlpha = Inputs.range([0.2, 3], {value: 1, step: 0.1, label: "Oja α (Oja's rule only)"})
viewof hbPause = Inputs.toggle({label: "Pause"})
viewof hbReplay = Inputs.button("Replay")







































Code
hbCol = ({C0: "#1f77b4", C1: "#ff7f0e", C2: "#2ca02c", K: "#444", T1: "#9467bd", T2: "#17becf"})
hbLay = ({W: 760, H: 400, S: 340, m: 80, top: 16})   // plane occupies x in [m, m+S], y in [top, top+S]
mutable hbClick = null
hbCanvas = {
  const c = mkCanvas(hbLay.W, hbLay.H);
  c.canvas.style.cursor = "crosshair";
  c.canvas.addEventListener("click", ev =&gt; {
    const r = c.canvas.getBoundingClientRect();
    const x = (ev.clientX - r.left) * hbLay.W / r.width, y = (ev.clientY - r.top) * hbLay.H / r.height;
    const {m, S, top} = hbLay;
    if (x &lt; m || x &gt; m + S || y &lt; top || y &gt; top + S) return;
    mutable hbClick = {fx: (x - m) / S, fy: 1 - (y - top) / S};
  });
  return c;
}
hbLimits = ({hebb: [-2, 2], bounded: [-0.1, 1.1], oja: [-1.2, 1.2]})
hbStart = {
  const [lo, hi] = hbLimits[hbRule];
  if (!hbClick) return [0.01, 0.05];
  return [lo + (hi - lo) * hbClick.fx, lo + (hi - lo) * hbClick.fy];
}
hbStep = (w, rule, q, alpha, dt = 0.1) =&gt; {
  const Qw = [w[0] + q * w[1], q * w[0] + w[1]];
  let n;
  if (rule === "oja") { const wQw = w[0] * Qw[0] + w[1] * Qw[1];
    n = [w[0] + dt * (Qw[0] - alpha * wQw * w[0]), w[1] + dt * (Qw[1] - alpha * wQw * w[1])]; }
  else n = [w[0] + dt * Qw[0], w[1] + dt * Qw[1]];
  if (rule === "bounded") n = [Math.min(1, Math.max(0, n[0])), Math.min(1, Math.max(0, n[1]))];
  return n;
}
hbEndColour = (w, rule) =&gt; {
  const near = (a, b, tol) =&gt; Math.abs(w[0] - a) &lt; tol && Math.abs(w[1] - b) &lt; tol;
  if (rule === "bounded") { if (near(1, 1, 1e-3)) return hbCol.C0; if (near(0, 1, 1e-3)) return hbCol.C1; if (near(1, 0, 1e-3)) return hbCol.C2; }
  if (rule === "oja") { const r = Math.SQRT1_2; if (near(r, r, 0.02)) return hbCol.C0; if (near(-r, r, 0.02)) return hbCol.C1; if (near(r, -r, 0.02)) return hbCol.C2; }
  return hbCol.K;
}
hbField = {
  const N = 20, steps = 100, trajs = [];
  for (let i = 0; i &lt; N; i++) for (let j = 0; j &lt; N; j++) {
    let w = [i / (N - 1), j / (N - 1)]; const pts = [w];
    for (let s = 0; s &lt; steps; s++) { w = hbStep(w, hbRule, hbQ, hbAlpha); pts.push(w); }
    trajs.push({pts, col: hbEndColour(w, hbRule)});
  }
  return trajs;
}
hbTraj = {
  hbReplay;
  const steps = 100; let w = hbStart; const pts = [w]; let k = 0;
  while (true) {
    if (!viewof hbPause.value && k &lt; steps) { w = hbStep(w, hbRule, hbQ, hbAlpha); pts.push(w); k++; }
    yield {pts, done: k &gt;= steps, col: k &gt;= steps ? hbEndColour(w, hbRule) : hbCol.K};
  }
}










































































Code
{
  const c = hbCanvas, fg = exFg(), {W, H, S, m, top} = hbLay;
  const [lo, hi] = hbLimits[hbRule];
  const px = w =&gt; m + S * (w - lo) / (hi - lo), py = w =&gt; top + S * (1 - (w - lo) / (hi - lo));
  c.clearRect(0, 0, W, H); c.font = exFont;
  axisBox(c, m, top, S, S);
  c.fillStyle = fg; c.textAlign = "center";
  c.fillText("w₁", m + S / 2, top + S + 24); c.fillText(lo, px(lo), top + S + 24); c.fillText(hi, px(hi), top + S + 24);
  c.textAlign = "right"; c.fillText("w₂", m - 10, top + S / 2 + 5); c.fillText(lo, m - 8, py(lo) + 5); c.fillText(hi, m - 8, py(hi) + 5);
  c.save(); c.beginPath(); c.rect(m, top, S, S); c.clip();
  c.lineWidth = 1;
  for (const {pts, col} of hbField) {
    c.strokeStyle = col; c.globalAlpha = 0.25; c.beginPath();
    pts.forEach((p, i) =&gt; i ? c.lineTo(px(p[0]), py(p[1])) : c.moveTo(px(p[0]), py(p[1]))); c.stroke();
  }
  c.globalAlpha = 1; c.lineWidth = 2.5; c.strokeStyle = hbTraj.col; c.beginPath();
  hbTraj.pts.forEach((p, i) =&gt; i ? c.lineTo(px(p[0]), py(p[1])) : c.moveTo(px(p[0]), py(p[1]))); c.stroke();
  const last = hbTraj.pts[hbTraj.pts.length - 1], first = hbTraj.pts[0];
  c.fillStyle = hbTraj.col; c.beginPath(); c.arc(px(last[0]), py(last[1]), 6, 0, 2 * Math.PI); c.fill();
  c.strokeStyle = fg; c.lineWidth = 1.5; c.beginPath(); c.arc(px(first[0]), py(first[1]), 6, 0, 2 * Math.PI); c.stroke();
  c.restore();
  c.fillStyle = fg; c.textAlign = "left"; c.fillText(`start (${first[0].toFixed(2)}, ${first[1].toFixed(2)}) · click to move`, m + 8, top + 22);
  // time course, right
  const x0 = m + S + 70, tW = W - x0 - 16;
  const tx = i =&gt; x0 + tW * i / 100, ty = w =&gt; py(w);
  axisBox(c, x0, top, tW, S);
  c.fillStyle = fg; c.textAlign = "center"; c.fillText("time steps", x0 + tW / 2, top + S + 24);
  c.fillText("0", tx(0), top + S + 24); c.fillText("100", tx(100), top + S + 24);
  c.textAlign = "right"; c.fillText(lo, x0 - 8, py(lo) + 5); c.fillText(hi, x0 - 8, py(hi) + 5);
  c.save(); c.beginPath(); c.rect(x0, top, tW, S); c.clip();
  for (const [j, col] of [[0, hbCol.T1], [1, hbCol.T2]]) {
    c.strokeStyle = col; c.lineWidth = 2; c.beginPath();
    hbTraj.pts.forEach((p, i) =&gt; i ? c.lineTo(tx(i), ty(p[j])) : c.moveTo(tx(i), ty(p[j]))); c.stroke();
  }
  c.restore();
  c.textAlign = "left"; c.fillStyle = hbCol.T1; c.fillText("w₁", x0 + 8, top + 22); c.fillStyle = hbCol.T2; c.fillText("w₂", x0 + 44, top + 22);
  return c.canvas;
}







What you see. Left: the weight plane, \(w_1\) against \(w_2\). The faint lines are trajectories from a grid of starting points, coloured by where they end after 100 steps. With bounds: blue ends at \((1,1)\), orange at \((0,1)\), green at \((1,0)\). With Oja’s rule: blue ends at \((1,1)/\sqrt2\), orange at \((-1,1)/\sqrt2\), green at \((1,-1)/\sqrt2\). Grey means none of these, which for plain Hebbian learning is every trajectory, since they all run off to infinity. The thick line is your trajectory, starting at the open circle and ending at the filled dot, which takes the colour of its end state once it has arrived. Right: the same trajectory as \(w_1\) (purple) and \(w_2\) (teal) against time.
Try: plain Hebbian learning runs away along the leading eigenvector of \(Q\), whichever way you start. With bounds the plane splits into basins of attraction. Oja’s rule keeps \(|w|\) finite and converges to a normalised eigenvector of \(Q\). Change \(q\) to see the basins move. From the Hebbian learning exercise in Theoretical Neuroscience.

