Principal component analysis
Fisher’s iris data: 150 flowers, four measurements each. PCA finds the directions of largest variance, the eigenvectors of the covariance matrix.
\[C = \frac{1}{n} X^{\mathsf T} X, \qquad C\, e_k = \lambda_k e_k\]

\(X\): the data matrix, 150 rows (flowers) and 4 columns (sepal length, sepal width, petal length, petal width, in cm), with the column means removed. With standardisation on, each column is also divided by its standard deviation.
\(C\): the \(4 \times 4\) covariance matrix.
\(e_k\): the \(k\)-th principal component, a direction in the four-dimensional measurement space; \(\lambda_k\) its eigenvalue, the variance of the data along it.
Explained variance: \(\lambda_k / \sum_j \lambda_j\).



Code
irisRaw = FileAttachment("iris.json").json()
viewof pcStd = Inputs.toggle({label: "Standardise each variable (z-score)", value: true})
pcAxisOpts = new Map([["PC 1", "pc0"], ["PC 2", "pc1"], ["PC 3", "pc2"], ["PC 4", "pc3"],
  ...irisRaw.features.map((f, i) =&gt; [f, "v" + i])])
viewof pcX = Inputs.select(pcAxisOpts, {value: "pc0", label: "Horizontal axis"})
viewof pcY = Inputs.select(pcAxisOpts, {value: "pc1", label: "Vertical axis"})
viewof pcColour = Inputs.toggle({label: "Colour by species", value: true})














































Code
symEig = A =&gt; {           // Jacobi eigenvalue iteration for a small symmetric matrix
  const n = A.length, a = A.map(r =&gt; r.slice()), v = Array.from({length: n}, (_, i) =&gt; Array.from({length: n}, (_, j) =&gt; +(i === j)));
  for (let sweep = 0; sweep &lt; 60; sweep++) {
    let off = 0; for (let i = 0; i &lt; n; i++) for (let j = i + 1; j &lt; n; j++) off += a[i][j] ** 2;
    if (off &lt; 1e-18) break;
    for (let p = 0; p &lt; n; p++) for (let q = p + 1; q &lt; n; q++) {
      if (Math.abs(a[p][q]) &lt; 1e-15) continue;
      const th = (a[q][q] - a[p][p]) / (2 * a[p][q]), t = Math.sign(th || 1) / (Math.abs(th) + Math.sqrt(th * th + 1));
      const cs = 1 / Math.sqrt(t * t + 1), sn = t * cs;
      for (let k = 0; k &lt; n; k++) { const akp = a[k][p], akq = a[k][q]; a[k][p] = cs * akp - sn * akq; a[k][q] = sn * akp + cs * akq; }
      for (let k = 0; k &lt; n; k++) { const apk = a[p][k], aqk = a[q][k]; a[p][k] = cs * apk - sn * aqk; a[q][k] = sn * apk + cs * aqk; }
      for (let k = 0; k &lt; n; k++) { const vkp = v[k][p], vkq = v[k][q]; v[k][p] = cs * vkp - sn * vkq; v[k][q] = sn * vkp + cs * vkq; }
    }
  }
  const order = [...Array(n).keys()].sort((i, j) =&gt; a[j][j] - a[i][i]);
  return {values: order.map(i =&gt; a[i][i]), vectors: order.map(i =&gt; { const col = v.map(r =&gt; r[i]); const big = col.reduce((b, x) =&gt; Math.abs(x) &gt; Math.abs(b) ? x : b, 0); return big &lt; 0 ? col.map(x =&gt; -x) : col; })};
}
pca = {
  const rows = irisRaw.rows, d = 4, n = rows.length;
  const mean = Array.from({length: d}, (_, j) =&gt; rows.reduce((s, r) =&gt; s + r[j], 0) / n);
  const sd = Array.from({length: d}, (_, j) =&gt; Math.sqrt(rows.reduce((s, r) =&gt; s + (r[j] - mean[j]) ** 2, 0) / n));
  const X = rows.map(r =&gt; Array.from({length: d}, (_, j) =&gt; (r[j] - mean[j]) / (pcStd ? sd[j] : 1)));
  const C = Array.from({length: d}, (_, i) =&gt; Array.from({length: d}, (_, j) =&gt; X.reduce((s, x) =&gt; s + x[i] * x[j], 0) / n));
  const {values, vectors} = symEig(C);
  const scores = X.map(x =&gt; vectors.map(e =&gt; e.reduce((s, ei, j) =&gt; s + ei * x[j], 0)));
  const total = values.reduce((s, l) =&gt; s + l, 0);
  return {X, C, values, vectors, scores, total, species: rows.map(r =&gt; r[4]), mean, sd};
}
